import * as util from 'node:util';
function main(): void {
  const u: any = util;
  const t: any = new u.MIMEType('text/html; charset=utf-8');
  console.log(Object.keys(t), Object.keys(t.params), Object.keys(new TextDecoder()), Object.keys(new u.MIMEParams()));
  console.log(t.essence, t.params.get('charset'), new TextDecoder('utf-8', { fatal: true }).fatal);
}
